arguments.argument:
sx = floor(view_xview / fgrid);
sy = floor(view_yview / fgrid);
ex = sx + dw;
ey = sy + dh;
surface_set_target(surf);
draw_clear(0);

texture_set_interpolation(true)

for (j = sy; j < ey; j += 1)
{
for (i = sx; i < ex; i += 1)
{
if falp[i, j]=2{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, c_dkgray, 1)}
//반투명 포그를그림
if falp[i, j]=1{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, c_dkgray, 1)}

if falp[i, j]=0{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, $ffffff, 0)}
//포그를 없앰
}
}

for (j = sy; j < ey; j += 1)
{
for (i = sx; i < ex; i += 1)
{
if falp[i, j]=1{draw_sprite_ext(spr_Fog, 0, i * fgrid - view_xview, j * fgrid - view_yview, fscale, fscale, 0, $ffffff, 1)}
//포그를 그림
}
}

texture_set_interpolation(false)

surface_reset_target();

with(obj_unit){if player=global.player_control{other.ok_rr=1}}
if ok_rr=0{with(obj_bil){if player=global.player_control{other.ok_rr=1}}}

with(obj_unit)
{
if global.player_control=player or other.ok_rr=0
{
sk_fog_obj(sys_fog, x, y, range, 2)
}
//반투명
}
